// Extend the capability of File to be transformed into a Box<dyn IoBoxed>
trait IntoIOBoxed {
    fn into_io_boxed(self) -> Box<dyn IoBoxed>;
}

impl IntoIOBoxed for File {
    fn into_io_boxed(self) -> Box<dyn IoBoxed> {
        Box::new(self)
    }
