use tiny_elf_riscv64::{TinyU8, TinyU64};

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: {} <bin_file>", args[0]);
        process::exit(1);
    }

    let vm_bin_filename = &args[1];
    match run_vm(vm_bin_filename, &args) {
