fn run_elf(vm: &mut tiny_elf_riscv64::ElfVM, data_file: &str, entry_point: u64) -> Result<i32, String> {
    use std::io::BufReader;

    let stdin_fd = 0;
    let stdout_fd = 1;
    let stderr_fd = 2;

    let pDataStream = File::open(data_file).map(BufReader::new).map_err(|_| {
