            && self.e_ident[2] == b'L'
            && self.e_ident[3] == b'F'
            && self.e_ident[4] == 2
            && self.e_ident[5] == 1
            && self.e_ident[6] == 1
            && self.e_machine == 0xF3
            && [2, 3].contains(&self.e_type)
    }
