                } else {
                    self.x[10] = !9;
                }
            },
            56 | 65 | 66 | 79 | 80 => {
                self.x[10] = !38;
            },
            160 => {
                self.x[10] = !38;
            },
            113 | 169 => {
                self.x[10] = !22;
            },
            174 | 175 | 176 | 177 => {
                self.x[10] = 0;
            },
            96 => {
                self.x[10] = 1;
            },
            99 | 100 | 261 | 132 | 134 | 135 => {
