            },
            220 | 221 => {
                self.x[10] = !38;
            },
            _ => panic!("ecall: unsupported syscall number {} (a0={}, a1=0x{:x}, a2={}) at pc=0x{:x}", num, a0, a1, a2, self.pc - 4),
