const EI_CLASS: u8 = 4;
const ELFCLASS64: u8 = 2;
const EI_DATA: u8 = 5;
const ELFDATA2LSB: u8 = 1;
const EI_VERSION: u8 = 6;
const EV_CURRENT: u8 = 1;
const EM_RISCV: u16 = 0xF3;
const ET_EXEC: u16 = 2;
const PT_LOAD: u32 = 1;

type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

